const presets = [
  {
    template_name: 'Congestion Study',
    goal: 'Identify where and when crowding occurs in a monitored space',
    default_behaviors: ['entry clustering', 'standing clusters', 'queuing', 'high-density occupancy'],
    recommended_duration: '2 weeks',
    recommended_outputs: ['peak congestion times', 'zone hotspot chart', 'entry bottleneck summary', 'layout recommendations'],
    example_user_friendly_explanation: 'Use this when you want to find crowding hotspots and understand when bottlenecks happen.'
  },
  {
    template_name: 'Space Utilization Study',
    goal: 'Understand which zones are underused, overused, or unevenly used over time',
    default_behaviors: ['occupancy presence', 'seat use', 'linger duration', 'repeat zone use'],
    recommended_duration: '2 to 4 weeks',
    recommended_outputs: ['zone utilization chart', 'hourly occupancy trend', 'underused-area summary'],
    example_user_friendly_explanation: 'Use this to see which areas people actually use and which layouts are being ignored.'
  },
  {
    template_name: 'Interaction / Collaboration Study',
    goal: 'Identify where collaboration and small-group interaction naturally emerge',
