    goal: 'Look for visible behaviors that may signal discomfort related to temperature or airflow conditions',
    default_behaviors: ['layer adjustment', 'restlessness', 'frequent relocation', 'window/door proximity clustering'],
    recommended_duration: '1 to 2 weeks',
    recommended_outputs: ['comfort proxy timeline', 'zone discomfort signals', 'possible HVAC/layout follow-ups'],
    example_user_friendly_explanation: 'Use this when you suspect discomfort but want visible behavior clues before deeper diagnostics.'
  },
  {
    template_name: 'Entrance / Flow Study',
    goal: 'Understand how people move through monitored entry and transition zones',
    default_behaviors: ['entry surges', 'door hesitation', 'queue formation', 'directional flow imbalance'],
    recommended_duration: '1 to 2 weeks',
    recommended_outputs: ['entry flow trend', 'surge windows', 'bottleneck summary', 'wayfinding/layout recommendations'],
    example_user_friendly_explanation: 'Use this to understand movement patterns, surges, and possible entry bottlenecks.'
  }
];

return [{
  json: {
    user_id: body.user_id ?? null,
    session_id: body.session_id ?? null,
    message_text: body.message_text ?? body.message ?? '',
    building_id: body.building_id ?? null,
    study_id: body.study_id ?? null,
    debug_mode: body.debug_mode ?? false,
    recommended_presets_catalog: presets,
    chat_request: body,
  }
}];

const item = $input.first().json;
const output = item.output ?? item.text ?? item.response ?? item.data ?? item;
let parsed = output;
const errors = [];
if (typeof parsed === 'string') {
  try {
    parsed = JSON.parse(parsed);
  } catch (error) {
    errors.push('json_parse_failed');
  }
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  errors.push('payload_not_object');
  parsed = {};
}
for (const field of ["action_type","assistant_response_text"]) {
  if (!(field in parsed)) errors.push(`missing_${field}`);
}
return [{
  json: {
    raw_ai_output: output,
    parsed_output: parsed,
    validation_passed: errors.length === 0,
    validation_errors: errors,
  }
}];

